def responsabilidad_del_cliente(modelo):
    mapa = {
        "IaaS": ["sistema operativo", "aplicaciones", "configuracion de red"],
        "PaaS": ["aplicacion", "datos"],
        "SaaS": ["gestion de accesos", "datos subidos"],
    }
    return mapa.get(modelo, [])

for modelo in ["IaaS", "PaaS", "SaaS"]:
    print(f"{modelo}: {responsabilidad_del_cliente(modelo)}")
